<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase'
const products=ref<any[]>([]),suppliers=ref<any[]>([]),purchases=ref<any[]>([]),supplier=ref<number|null>(null),reference=ref(''),mode=ref('received'),items=ref<any[]>([]),error=ref(''),busy=ref(false)
const quantity=(x:any)=>Number(x.packs||0)*Number(x.pack_size||1)+Number(x.loose||0)
const total=computed(()=>items.value.reduce((s,x)=>s+quantity(x)*Number(x.unit_cost||0),0))
async function load(){const [p,s,h]=await Promise.all([supabase.from('products').select('id,name,sku,stock').order('name'),supabase.from('suppliers').select('id,name').order('name'),supabase.from('purchases').select('*,suppliers(name)').order('created_at',{ascending:false}).limit(100)]);if(p.error||s.error||h.error)error.value=p.error?.message??s.error?.message??h.error?.message??'';products.value=p.data??[];suppliers.value=s.data??[];purchases.value=h.data??[]}
function add(){items.value.push({product_id:products.value[0]?.id??null,packs:0,pack_size:1,loose:1,unit_cost:0})}
async function submit(){busy.value=true;error.value='';try{const {data,error:e}=await supabase.rpc('create_purchase',{p_supplier_id:supplier.value,p_reference:reference.value,p_status:mode.value,p_items:items.value.map(x=>({product_id:Number(x.product_id),quantity:quantity(x),packs:Number(x.packs||0),pack_size:Number(x.pack_size||1),unit_cost:Number(x.unit_cost)}))});if(e)throw e;items.value=[];reference.value='';supplier.value=null;await load();alert(mode.value==='received'?`Purchase ${data} received; stock has been updated.`:`Purchase order ${data} saved. Receive it from the history list when goods arrive.`)}catch(e:any){error.value=e.message??'Purchase failed'}finally{busy.value=false}}
async function receive(p:any){busy.value=true;error.value='';try{const {error:e}=await supabase.rpc('receive_purchase',{p_purchase_id:p.id});if(e)throw e;await load()}catch(e:any){error.value=e.message??'Could not receive purchase'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>Purchases</h1><p>Create purchase orders or receive stock from suppliers.</p></div></div><p v-if="error" class="alert">{{error}}</p><div class="panel"><h2>New purchase</h2><div class="sales-grid"><label>Supplier<select v-model="supplier" class="control"><option :value="null">Select supplier</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Invoice / reference<input v-model="reference" class="control"></label><label>Purchase status<select v-model="mode" class="control"><option value="received">Receive immediately</option><option value="ordered">Save as order (do not update stock)</option></select></label></div><div v-for="(it,i) in items" :key="i" class="cart-line purchase-line"><select v-model="it.product_id" class="control"><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}} ({{p.sku}})</option></select><label>Loose units<input v-model.number="it.loose" type="number" min="0" class="control qty"></label><label>Packs<input v-model.number="it.packs" type="number" min="0" class="control qty"></label><label>Pack size<input v-model.number="it.pack_size" type="number" min="1" class="control qty"></label><label>Unit cost<input v-model.number="it.unit_cost" type="number" min="0" step="0.01" class="control qty"></label><small>{{quantity(it)}} total units</small><button class="link danger" @click="items.splice(i,1)">Remove</button></div><button class="btn" @click="add" :disabled="!products.length">＋ Add product</button><div class="totals"><div>Purchase total <b>UGX {{total.toLocaleString()}}</b></div></div><button class="btn primary" :disabled="busy||!items.length||items.some(x=>!x.product_id||quantity(x)<1||x.unit_cost<0)" @click="submit">{{busy?'Saving…':mode==='received'?'Receive purchase & update stock':'Save purchase order'}}</button></div><div class="panel mt"><h2>Purchase history</h2><div class="table-scroll"><table><thead><tr><th>Reference</th><th>Supplier</th><th>Status</th><th>Total cost</th><th>Date</th><th>Action</th></tr></thead><tbody><tr v-for="p in purchases" :key="p.id"><td>{{p.reference??p.id}}</td><td>{{p.suppliers?.name??'—'}}</td><td>{{p.status}}</td><td>UGX {{Number(p.total_cost).toLocaleString()}}</td><td>{{new Date(p.created_at).toLocaleString()}}</td><td><button v-if="p.status==='ordered'" class="link" :disabled="busy" @click="receive(p)">Receive stock</button></td></tr></tbody></table></div></div></section></template>
